pub fn describe(
    memory: &Memory<'_>,
    input: DescribeRequest,
) -> MemoryResult<crate::task_verb::TaskDescription> {
    Ok(if input.self_target {
        Err(MemoryError::bad_request(
            "describe(self) requires a bound run session",
        ))?
    } else if input.vault {
        memory.describe_vault(&input)?
    } else if input.key.is_some() {
        Err(MemoryError::bad_request(
            "describe(card key) expands a board card, which only a live board session holds",
        ))?
    } else if input.fold.is_some() {
        Err(MemoryError::bad_request(
            "describe(fold) peeks at a fold of a run's own log, which only that run's code mode holds",
        ))?
    } else if input.handle.is_some() || input.after.is_some() {
        crate::task_verb::sdk::describe_handle_status(memory, &input)?
    } else {
        memory.describe(
            input
                .task_ref
                .as_deref()
                .map(crate::EntityId::from_hex)
                .transpose()?,
        )?
    })
}
pub fn tasks_create(
    memory: &Memory<'_>,
    input: TaskCreateRequest,
) -> MemoryResult<crate::task_verb::TaskCreateReceipt> {
    let unlinked_prose = crate::gate::record_references::unlinked_prose_links(
        memory,
        "tasks.create",
        &input,
        &[
            "/label",
            "/spec/title",
            "/spec/description",
            "/spec/brief",
            "/spec/notes",
            "/spec/instructions",
        ],
    )?;
    crate::gate::record_references::admit_row_references(
        memory,
        "tasks.create",
        &input,
        &["/parent_ref"],
    )?;
    let landed = memory.tasks_create(&crate::task_verb::sdk::task_create_spec(memory, input)?)?;
    crate::gate::record_references::receipt_landed_prose(memory, &unlinked_prose);
    Ok(landed)
}
